import {
  array,
  createTypeContext,
  declare,
  docComment,
  object,
  type JsonSchema,
  typeDeclaration,
} from "./render-defs.js";

const header = `// Generated by tooling/generate-types from definitions/runtime.schema.json.
// Do not edit by hand.
`;

const diagnosticCode = "DiagnosticCode";

/**
 * \`DiagnosticCode\` lists the codes the engine knows and stays open to any string, because an
 * engine newer than the SDK can report a code it doesn't list.
 */
function renderDiagnosticCode(def: JsonSchema): string {
  const codes = array(def["x-lumen-codes"]).map(object);
  if (codes.length === 0) throw new Error("`DiagnosticCode` lists no codes");
  const union = codes.map((entry) => `  | ${JSON.stringify(entry.code)}`).join("\n");
  return `${docComment(def.description, "")}export type ${diagnosticCode} =
${union}
  | (string & {});

/** Each diagnostic code and the severity of the diagnostics that carry it. */
export const diagnosticCodes = [
${codes.map((entry) => `  { code: ${JSON.stringify(entry.code)}, severity: ${JSON.stringify(entry.severity)} },`).join("\n")}
] as const;`;
}

/** The contents of `generated/runtime.ts`: the types of the values the engine returns. */
export function renderRuntimeTypes(schema: JsonSchema): string {
  const defs = object(schema.$defs) as Record<string, JsonSchema>;
  const context = createTypeContext(defs, [], true);
  for (const [name, def] of Object.entries(defs)) {
    if (name !== diagnosticCode) declare(context, name, typeDeclaration(name, def, context, true));
  }
  const codeDef = defs[diagnosticCode];
  if (codeDef === undefined) throw new Error("the runtime schema has no `DiagnosticCode`");
  return `${header}
${renderDiagnosticCode(codeDef)}

${[...context.declarations.values()].join("\n\n")}
`;
}
